SELECT 
FROM question
WHERE category_id = #{categoryId}
  AND status = 1
ORDER BY id ASC
LIMIT #{limit}

SELECT 
FROM question
WHERE category_id = #{categoryId}
  AND status = 1
ORDER BY RAND()
LIMIT #{limit}

SELECT id, category_id, question_type, content, options, answer, analysis, difficulty, status
FROM question
WHERE id = #{id}
